# area: protocols
# hypothesis: a plain class satisfies a generic Protocol only when it defines every member, while an explicit subclass inherits the default method body.
from typing import Protocol, TypeVar, reveal_type

T_co = TypeVar('T_co', covariant=True)


class Source(Protocol[T_co]):
    @property
    def value(self) -> T_co: ...

    def describe(self) -> str:
        return f'Source({self.value!r})'


class Gauge(Source[int]):
    def __init__(self, n: int) -> None:
        self._n = n

    @property
    def value(self) -> int:
        return self._n


class Counter:
    def __init__(self, n: int) -> None:
        self._n = n

    @property
    def value(self) -> int:
        return self._n


def show(src: Source[int]) -> str:
    return src.describe()


g = Gauge(3)
reveal_type(g.value)
shown = show(g)
reveal_type(shown)


def guarded() -> str:
    try:
        return show(Counter(4))  # expect-error: Counter has no describe
    except AttributeError:
        return 'missing describe'


outcome = guarded()
reveal_type(outcome)
